import {VERSION,APP_KEY,MAX_FILES,MAX_PROJECT_BYTES,MAX_NOTES,MAX_AUDIT,PROVIDERS,VIEWS,CAPABILITIES,FLOW_TEMPLATES,uid,now,clone,providerById,safeName,safeFiles,starterProject,freshState,validateState,migrateLegacy,csvSummary,routeDescription,historyForRoute} from './core.js';
import {read,write,remove,storageMode,isDurableStorage} from './storage.js';
import {KeyVault} from './vault.js';
import {callProvider,validateModel} from './provider-api.js';
import {RuntimeRunner,previewReport} from './sandbox.js';
import {zipFiles,unzipFiles} from './zip.js';
import {setupLabs} from './labs.js';
import {projectFolders,projectTreeEntries,moveProjectFolder} from './project-files.js';
import {parseNoteArchive,exportNoteArchive} from './knowledge.js';

const el=id=>document.getElementById(id);
const qs=s=>document.querySelector(s);
const qsa=s=>Array.from(document.querySelectorAll(s));
const guideById=new Map((window.MM_PROVIDER_GUIDES||[]).map(g=>[g.id,g]));
const vault=new KeyVault();
let state,run,labs,pythonRuntimeStatus='UNTESTED',lastRunLang=null,activeView='overview',activeNote=null,saveTimer=null,toastTimer=null,activeChatControllers=[],workflowController=null,storageFailed=false,recoveryRaw=null,recoveryKind=null;
const $=el;
function toast(message,error=false){const t=$('toast');t.textContent=String(message).slice(0,400);t.classList.toggle('error',error);t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,5200);}
function errorText(e){return typeof e==='string'?e:e?.message||String(e);}
function formatTime(t){try{return new Date(t).toLocaleString()}catch{return String(t)}}
function make(tag,cls,text){const node=document.createElement(tag);if(cls)node.className=cls;if(text!==undefined)node.textContent=String(text);return node;}
function clearNode(node){node.replaceChildren();return node;}
function savedStatus(){return isDurableStorage()?'Saved on this device':'Temporary memory only — export a backup';}
function saveSoon(){if(storageFailed)return;clearTimeout(saveTimer);const status=$('save-indicator');if(status)status.textContent='Saving…';saveTimer=setTimeout(async()=>{try{await write('state.v1',state);if(status)status.textContent=savedStatus();}catch(e){storageFailed=true;if(status)status.textContent='Save failed — export a backup';toast('Local storage failed: '+errorText(e),true);}},300);}
async function saveNow(){clearTimeout(saveTimer);try{await write('state.v1',state);$('save-indicator').textContent=savedStatus();}catch(e){storageFailed=true;$('save-indicator').textContent='Save failed — export a backup';toast('Save failed: '+errorText(e),true);throw e;}}
async function replaceWorkspace(next){if(!validateState(next))throw Error('Invalid workspace replacement');clearTimeout(saveTimer);await write('state.v1',next);state=next;activeNote=null;storageFailed=false;$('save-indicator').textContent=savedStatus();renderAll();}
function project(){return state.projects.find(p=>p.id===state.activeProjectId)||state.projects[0];}
function thread(){return state.threads.find(t=>t.id===state.activeThreadId)||state.threads[0];}
function audit(op,provider,status,usage){state.audit.unshift({id:uid('event'),at:now(),op,provider,status,usage:usage?{prompt_tokens:usage.prompt_tokens??null,completion_tokens:usage.completion_tokens??null,total_tokens:usage.total_tokens??null,source:usage.source||'unknown'}:null});state.audit=state.audit.slice(0,MAX_AUDIT);saveSoon();renderAudit();renderStats();}
function selectView(view){if(!VIEWS[view])return;activeView=view;for(const node of qsa('.screen'))node.hidden=node.dataset.screen!==view;for(const b of qsa('[data-view]')){const current=b.dataset.view===view;b.classList.toggle('selected',current);b.setAttribute('aria-current',current?'page':'false')}const label=$('current-view-label');label.textContent=VIEWS[view];$('sidebar').classList.remove('open');$('nav-backdrop').hidden=true;$('mobile-menu').setAttribute('aria-expanded','false');if(view==='overview')renderStats();if(view==='providers')renderProviders();if(view==='vault')renderVault();if(view==='chat')renderChat();if(view==='usage')renderAudit();if(view==='workflows')renderWorkflows();if(view==='knowledge')renderKnowledge();if(view==='settings')renderSettings();if(view==='capabilities')renderCapabilities();history.replaceState(null,'',`#${view}`);}
function renderHealth(){const checks=[['Browser storage',!storageFailed&&isDurableStorage()?'PERSISTENT':'TEMPORARY'],['JavaScript Workers',typeof Worker==='function'?'AVAILABLE':'UNAVAILABLE'],['Key vault',vault.isUnlocked?'UNLOCKED':'LOCKED'],['Provider calls','UNVERIFIED'],['Python execution',pythonRuntimeStatus],['Offline shell',navigator.serviceWorker?.controller?'CONTROLLING':'INACTIVE']];const host=clearNode($('health-list'));for(const [name,status] of checks){const row=make('div','health-line');row.append(make('span','health-icon pending','○'),make('span','',name),make('strong','',status));host.append(row);}}
function renderStats(){const p=project();$('stat-project').textContent=p?.name||'Workspace';$('stat-files').textContent=Object.keys(p?.files||{}).length;$('stat-routes').textContent=routeDescription(vault.count);$('stat-requests').textContent=String(state.audit.filter(x=>x.op==='inference').length);$('sidebar-runtime').textContent=`${state.projects.length} project(s) · ${vault.count} saved key slot(s)`;$('connection-badge').textContent=vault.isUnlocked&&vault.count?'● KEY VAULT UNLOCKED':'● LOCAL MODE';renderHealth();}
function renderProjectSelector(){const select=$('project-select'),old=select.value;select.replaceChildren();for(const p of state.projects){const option=new Option(p.name,p.id);select.add(option);}select.value=state.activeProjectId;const snaps=$('snapshot-select'),prior=snaps.value;snaps.replaceChildren(new Option('Choose snapshot…',''));state.snapshots.filter(s=>s.project.id===state.activeProjectId).slice().reverse().forEach(s=>snaps.add(new Option(`${s.pinned?'📌 ':''}${s.label} · ${formatTime(s.at)}`,s.id)));if([...snaps.options].some(o=>o.value===prior))snaps.value=prior;renderSnapshotActions();}
function renderFiles(){renderProjectSelector();const p=project();const tree=clearNode($('file-tree'));for(const entry of projectTreeEntries(p.files)){if(entry.type==='folder'){const heading=make('div','folder-entry','📁 '+entry.path.split('/').at(-1));heading.title=entry.path;heading.style.paddingLeft=Math.min(11+entry.depth*14,60)+'px';tree.append(heading);continue;}const name=entry.path;const button=make('button','file-entry'+(name===p.active?' active':''),`${name.toLowerCase().endsWith('.py')?'🐍':name.toLowerCase().endsWith('.html')?'◇':name.toLowerCase().endsWith('.css')?'▥':'▤'} ${name.split('/').at(-1)}`);button.type='button';button.title=name;button.style.paddingLeft=Math.min(11+entry.depth*14,60)+'px';button.addEventListener('click',()=>{p.active=name;renderFiles();saveSoon()});tree.append(button);}const editor=$('code-editor');if(editor.value!==p.files[p.active])editor.value=p.files[p.active]||'';$('active-file').textContent=p.active;renderGutter();renderStats();}
function renderGutter(){const editor=$('code-editor');const lines=Math.min(2500,editor.value.split('\n').length);$('line-gutter').textContent=Array.from({length:lines},(_,i)=>i+1).join('\n');}
function editFile(){const p=project(),prior=p.files[p.active];p.files[p.active]=$('code-editor').value;if(!safeFiles(p.files)){p.files[p.active]=prior;$('code-editor').value=prior;toast(`Project limit: ${MAX_FILES} files and ${MAX_PROJECT_BYTES} total characters.`,true);return;}p.updated=now();renderGutter();saveSoon();renderStats();}
function createProject(){if(state.projects.length>=30)return toast('Maximum 30 projects.',true);const name=prompt('Project name:','Untitled project');if(!name)return;const p=starterProject(name.slice(0,90));state.projects.push(p);state.activeProjectId=p.id;renderFiles();saveSoon();toast('Project created.');}
function renameProject(){const p=project();const name=prompt('Rename project:',p.name);if(!name)return;p.name=name.slice(0,90);renderProjectSelector();renderStats();saveSoon();}
function deleteProject(){if(state.projects.length<=1)return toast('Keep at least one project.',true);const p=project();if(!confirm(`Delete project "${p.name}" from this browser? Export a backup first if needed.`))return;state.projects=state.projects.filter(x=>x.id!==p.id);state.activeProjectId=state.projects[0].id;renderFiles();saveSoon();}
function newFile(){const p=project();const name=prompt('New file name (folders can be included, e.g. src/utils.js):');if(name===null)return;if(!safeName(name)||Object.hasOwn(p.files,name)||Object.keys(p.files).length>=MAX_FILES)return toast('Invalid, duplicate, or excessive filename.',true);p.files[name]='';p.active=name;renderFiles();saveSoon();$('code-editor').focus();}
function renameFile(){const p=project();const name=prompt('Rename file:',p.active);if(!name||name===p.active)return;if(!safeName(name)||Object.hasOwn(p.files,name))return toast('Invalid or duplicate filename.',true);const result={};for(const [file,text] of Object.entries(p.files))result[file===p.active?name:file]=text;p.files=result;p.active=name;renderFiles();saveSoon();}
function moveFolder(){
 const p=project(),folders=projectFolders(p.files);if(!folders.length)return toast('This project has no nested folders yet.',true);
 const suggested=p.active.includes('/')?p.active.slice(0,p.active.lastIndexOf('/')):folders[0];
 const from=prompt('Folder to move (available: '+folders.join(', ')+'):',suggested);if(from===null)return;
 const to=prompt('Move all files in "'+from+'" to which relative folder path? (e.g. src/lib):');if(to===null)return;
 try{const result=moveProjectFolder(p.files,p.active,from.trim(),to.trim());
 if(!confirm('Move '+result.moved.length+' file(s) from "'+from.trim()+'" into "'+to.trim()+'"? Existing files will not be overwritten.'))return;
 p.files=result.files;p.active=result.active;p.updated=now();renderFiles();saveSoon();toast('Moved '+result.moved.length+' project file(s).');
 }catch(error){toast('Folder move rejected: '+error.message,true);}
}
function deleteFile(){const p=project();if(Object.keys(p.files).length===1)return toast('A project needs at least one file.',true);if(!confirm(`Delete ${p.active}?`))return;delete p.files[p.active];p.active=Object.keys(p.files)[0];renderFiles();saveSoon();}
function snapshot(){const p=project();const input=prompt('Snapshot label:','Checkpoint');if(input===null)return;const label=input.trim().slice(0,60);if(!label)return toast('Snapshot needs a label.',true);
 if(state.snapshots.length>=100){const oldest=state.snapshots.findIndex(s=>!s.pinned);if(oldest<0)return toast('All 100 snapshots are pinned. Unpin or delete one first.',true);if(!confirm('Snapshot storage is full. Replace the oldest unpinned snapshot "'+state.snapshots[oldest].label+'"? Export it first if needed.'))return;state.snapshots.splice(oldest,1);}
 const record={id:uid('snapshot'),at:now(),label,project:clone(p),pinned:false};
 state.snapshots.push(record);renderProjectSelector();$('snapshot-select').value=record.id;renderSnapshotActions();saveSoon();toast('Snapshot saved locally.');
}
function selectedSnapshot(){return state.snapshots.find(s=>s.id===$('snapshot-select').value&&s.project.id===state.activeProjectId)||null;}
function renderSnapshotActions(){const selected=selectedSnapshot();$('restore-snapshot').disabled=!selected;$('snapshot-action-run').disabled=!selected;const pin=$('snapshot-action').querySelector('option[value="pin"]');if(pin)pin.textContent=selected?.pinned?'Unpin snapshot':'Pin snapshot';}
function manageSnapshot(){
 const snap=selectedSnapshot();if(!snap)return toast('Select a saved snapshot first.',true);
 const action=$('snapshot-action').value;
 if(action==='rename'){const entered=prompt('Rename selected snapshot:',snap.label);if(entered===null)return;const name=entered.trim().slice(0,60);if(!name)return toast('Snapshot label cannot be blank.',true);snap.label=name;renderProjectSelector();saveSoon();toast('Snapshot renamed.');return;}
 if(action==='export'){const payload={format:'mm-platform-snapshot-v1',name:snap.project.name,active:snap.project.active,files:snap.project.files,snapshot:{label:snap.label,at:snap.at}};download('snapshot-'+snap.label.replace(/[^a-z0-9_-]/gi,'_')+'.json',JSON.stringify(payload,null,2),'application/json');toast('Snapshot exported as an importable project.');return;}
 if(action==='pin'){snap.pinned=!snap.pinned;renderProjectSelector();saveSoon();toast(snap.pinned?'Snapshot protected from automatic eviction.':'Snapshot unpinned.');return;}
 if(action==='delete'){if(!confirm('Permanently delete snapshot "'+snap.label+'"? This does not delete your current project.'))return;state.snapshots=state.snapshots.filter(s=>s.id!==snap.id);$('snapshot-select').value='';renderProjectSelector();$('snapshot-comparison').hidden=true;saveSoon();toast('Snapshot deleted.');return;}
 if(action==='compare'){const current=project().files,old=snap.project.files,names=[...new Set([...Object.keys(old),...Object.keys(current)])].sort(),added=[],removed=[],changed=[],identical=[];for(const name of names){if(!Object.hasOwn(old,name))added.push(name);else if(!Object.hasOwn(current,name))removed.push(name);else if(old[name]!==current[name])changed.push(name);else identical.push(name);}
 const section=(heading,items)=>heading+' ('+items.length+')'+(items.length?'\n  '+items.join('\n  '):'');
 $('snapshot-comparison').textContent=['Comparison with snapshot: '+snap.label,section('Added since snapshot',added),section('Removed since snapshot',removed),section('Modified since snapshot',changed),section('Unchanged',identical)].join('\n\n');$('snapshot-comparison').hidden=false;toast('Snapshot comparison ready.');}
}
function restoreSnapshot(){const s=state.snapshots.find(x=>x.id===$('snapshot-select').value);if(!s)return toast('Select a snapshot first.',true);if(!confirm('Replace your current project files with this snapshot?'))return;const idx=state.projects.findIndex(p=>p.id===state.activeProjectId);state.projects[idx]=clone(s.project);renderFiles();saveSoon();toast('Snapshot restored.');}
function download(name,data,type='application/json'){const blob=data instanceof Blob?data:new Blob([data],{type});const url=URL.createObjectURL(blob);const a=make('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function projectJSON(){const p=project();return JSON.stringify({format:'mm-platform-b01',active:p.active,files:p.files},null,2);}
async function importProject(file){if(!file||file.size>10_000_000)return toast('Import file must be under 10 MB.',true);try{let files,active,name=file.name.replace(/\.(zip|json)$/i,'');if(file.name.toLowerCase().endsWith('.zip')){files=await unzipFiles(await file.arrayBuffer());active=files['main.js']?'main.js':Object.keys(files)[0];}else{const payload=JSON.parse(await file.text());if(payload.format==='mm-platform-b01'){files=payload.files;active=payload.active;}else if(payload.files&&payload.active){files=payload.files;active=payload.active;}else throw Error('Not a supported project JSON format');}if(!safeFiles(files)||!Object.hasOwn(files,active))throw Error('Project contains unsafe names, excessive sizes or no valid active file.');if(!confirm(`Import ${Object.keys(files).length} files as a new project?`))return;const p={id:uid('project'),name:name.slice(0,90),active,files,updated:now()};if(state.projects.length>=30)throw Error('Project limit reached');state.projects.push(p);state.activeProjectId=p.id;renderFiles();saveSoon();toast('Imported project files.');}catch(e){toast('Import failed: '+errorText(e),true);}}
async function importTextFiles(input){const files=Array.from(input.files||[]);input.value='';if(!files.length)return;const p=project();let accepted=0;for(const file of files.slice(0,20)){const name=file.name;if(!safeName(name)||file.size>500000||Object.hasOwn(p.files,name))continue;const text=await file.text();if(Object.keys(p.files).length>=MAX_FILES)break;p.files[name]=text;if(!safeFiles(p.files)){delete p.files[name];break;}p.active=name;accepted++;}renderFiles();saveSoon();toast(`${accepted} text file(s) imported into current project.`);}
const consoleLimit=50000;let terminalLines=0;
function printConsole(text){const area=$('console-output');if(++terminalLines>180){if(terminalLines===181){run.stop();area.textContent=(area.textContent+'\n[Output flood limit reached; worker terminated.]').slice(0,consoleLimit);}return;}let next=area.textContent+(area.textContent?'\n':'')+String(text);if(next.length>consoleLimit)next=next.slice(0,consoleLimit)+'\n[Output truncated]';area.textContent=next;area.scrollTop=area.scrollHeight;}
function showExecTab(tab){$('console-pane').hidden=tab!=='console';$('preview-pane').hidden=tab!=='preview';$('show-console').classList.toggle('active',tab==='console');$('show-preview').classList.toggle('active',tab==='preview');}
function runCode(){const p=project(),filename=p.active;const setting=$('runtime-choice').value;const lang=setting==='auto'?(filename.endsWith('.py')?'python':'javascript'):setting;if(setting==='auto'&&!/\.(py|js|mjs|cjs)$/.test(filename))return toast('Choose a .js or .py file, or set the runtime manually.',true);showExecTab('console');terminalLines=0;$('console-output').textContent=`Running ${filename} in isolated ${lang==='python'?'Python/WebAssembly':'JavaScript'} worker…`;try{lastRunLang=lang;if(lang==='python')pythonRuntimeStatus='RUNNING — REQUIRES CDN';run.run(p.files[filename],lang,(type,msg)=>{if(lang==='python'){if(type==='done'&&msg.includes('Python execution complete.'))pythonRuntimeStatus='EXECUTED THIS SESSION';else if(type==='error')pythonRuntimeStatus='FAILED THIS SESSION';}if(type==='error')printConsole('ERROR: '+msg);else printConsole(msg);},lang==='python'?120000:6000);audit('run',lang,'started');}catch(e){toast(errorText(e),true);}}
function stopCode(){run.stop('Execution stopped by user.');}
function previewPage(){run.stop();const p=project();const html=p.active.endsWith('.html')?p.active:Object.keys(p.files).find(f=>f.endsWith('.html'));if(!html)return toast('Create or select an HTML file to preview.',true);try{const result=previewReport(p.files,html);const frame=make('iframe');frame.title='Opaque-origin local project preview';frame.setAttribute('sandbox','allow-scripts');frame.setAttribute('referrerpolicy','no-referrer');frame.srcdoc=result.document;$('preview-host').replaceChildren(frame);showExecTab('preview');toast(result.warnings.length?`Preview ${html}: ${result.warnings.length} unresolvable or unsupported reference(s), for example ${result.warnings[0]}`:`Previewing ${html}; only its referenced local CSS/classic JS are included.`,result.warnings.length>0);}catch(error){toast('Preview could not be built: '+errorText(error),true);}}

function renderProviders(query=$('provider-search').value||''){const host=clearNode($('provider-list'));let count=0;for(const p of PROVIDERS){const g=guideById.get(p.id);if(!(p.name+p.window+(g?.scope||'')+(g?.reset||'')).toLowerCase().includes(query.toLowerCase()))continue;count++;const card=make('article','provider-card');const top=make('div','provider-top');top.append(make('h2','',p.name),make('span','tag '+(vault.get(p.id)?'good':'muted'),vault.get(p.id)?'KEY SAVED':'NOT CONNECTED'));card.append(top,make('p','',g?.note||'Eligible recurring-free source.'));const tags=make('div','provider-meta');tags.append(make('span','tag',p.window),make('span','tag','REMAINING: UNKNOWN'));card.append(tags);if(g){const d=make('details');d.append(make('summary','','Setup instructions + quota scope'));d.append(make('p','','Quota scope: '+g.scope));d.append(make('p','','Published reset: '+g.reset));const ol=make('ol');for(const step of g.steps)ol.append(make('li','',step));d.append(ol);card.append(d);const links=make('div','provider-links');for(const [label,url] of [['Create account ↗',g.signup_url],['Get key ↗',g.key_url],['Docs ↗',g.docs_url],['Limits ↗',g.limits_url]]){if(!url)continue;const a=make('a','',label);a.href=url;a.target='_blank';a.rel='noopener noreferrer';links.append(a);}card.append(links);}const button=make('button','button secondary small',vault.get(p.id)?'Manage saved key →':'Connect a key →');button.type='button';button.addEventListener('click',()=>{$('key-provider').value=p.id;$('key-model').value=vault.get(p.id)?.model||p.model;$('key-account').value=vault.get(p.id)?.account||'';selectView('vault');});card.append(button);host.append(card);}if(!count)host.append(make('p','','No providers match this search.'));}
async function renderVault(){const exists=await vault.exists();$('vault-status').textContent=vault.isUnlocked?'UNLOCKED':exists?'LOCKED':'NOT CREATED';$('vault-status').className='tag '+(vault.isUnlocked?'good':'muted');$('vault-action-title').textContent=exists?'Unlock your encrypted vault':'Create your encrypted vault';$('vault-submit').textContent=exists?'Unlock vault':'Create vault';$('vault-entry-hint').textContent=vault.isUnlocked?'Vault unlocked. Enter your provider information and save it encrypted.':'You can enter provider information now. To save it securely, first create or unlock your vault using the passphrase field on this page.';$('vault-lock').disabled=!vault.isUnlocked;const host=clearNode($('vault-items'));if(!vault.isUnlocked){host.append(make('p','hint-line',exists?'Vault is locked. Enter your passphrase to access saved key slots.':'No vault created yet. Choose a passphrase to begin.'));}else{for(const entry of vault.list()){const div=make('div','vault-item'),description=make('div');description.append(make('b','',providerById(entry.id)?.name||entry.id),make('small','',`${entry.model} · saved ${formatTime(entry.updated)}`));const removeButton=make('button','text-button danger-text','Remove');removeButton.addEventListener('click',async()=>{if(!confirm(`Remove ${entry.id} credentials?`))return;await vault.drop(entry.id);renderAll();toast('Key slot removed.');});div.append(description,removeButton);host.append(div);}if(!vault.count)host.append(make('p','hint-line','No keys stored yet. Add your first eligible route.'));}renderStats();}
async function submitVault(event){event.preventDefault();const pass=$('vault-password').value;try{if(await vault.exists())await vault.unlock(pass);else await vault.create(pass);$('vault-password').value='';toast('Vault unlocked on this device.');renderAll();}catch(e){toast(errorText(e),true);}}
async function submitKey(event){event.preventDefault();if(!vault.isUnlocked){toast('Your details are ready. Create or unlock your vault with a passphrase first; the fields will stay filled.',true);$('vault-password').focus();$('vault-password').scrollIntoView({behavior:'smooth',block:'center'});return;}const id=$('key-provider').value,model=$('key-model').value.trim(),key=$('key-value').value.trim(),account=$('key-account').value.trim();try{validateModel(id,model);if(id==='cloudflare'&&!/^[a-f0-9]{32}$/i.test(account))throw Error('Cloudflare requires a 32-character account ID');await vault.put(id,{key,model,account,attested:$('key-attest').checked});$('key-value').value='';$('key-attest').checked=false;renderAll();toast(`Encrypted key slot saved for ${providerById(id).name}. Provider connection is not verified until a request succeeds.`);}catch(e){toast(errorText(e),true);}}
function routeChoices(){const list=vault.list();for(const select of [$('chat-route'),$('workflow-route')]){const prior=select.value;select.replaceChildren();if(!list.length){select.add(new Option('Unlock + save a key first',''));continue;}for(const entry of list){select.add(new Option(`${providerById(entry.id)?.name||entry.id} · ${entry.model}`,entry.id));}if(list.some(e=>e.id===prior))select.value=prior;}const ready=list.length;$('chat-connection-label').textContent=ready?`${ready} saved key slot(s) · not verified`:'Unlock vault + connect an eligible free key';renderCompareRoute();}
function renderCompareRoute(){const select=$('compare-route'),previous=select.value,primary=$('chat-route').value;select.replaceChildren(new Option('Choose another route…',''));for(const entry of vault.list().filter(e=>e.id!==primary))select.add(new Option(`${providerById(entry.id)?.name||entry.id} · ${entry.model}`,entry.id));if([...select.options].some(o=>o.value===previous))select.value=previous;else select.value='';$('compare-route-wrap').hidden=!$('compare-mode').checked;}
function renderThreadList(){const host=clearNode($('thread-list')),query=$('thread-search').value.trim().toLowerCase();let count=0;for(const t of state.threads.slice().reverse()){if(query&&!t.title.toLowerCase().includes(query)&&!t.messages.some(m=>m.content.toLowerCase().includes(query)))continue;count++;const b=make('button','thread-entry'+(t.id===state.activeThreadId?' active':''),t.title||'Conversation');b.type='button';b.addEventListener('click',()=>{if(activeChatControllers.length)return toast('Finish or stop the current model request before switching threads.',true);state.activeThreadId=t.id;renderChat();saveSoon()});host.append(b);}if(!count)host.append(make('p','hint-line','No matching conversations.'));}
function renderChat(){routeChoices();renderThreadList();const host=clearNode($('chat-messages'));const t=thread();if(!t.messages.length){const empty=make('div','chat-empty');empty.append(make('span','','✳'),make('h3','','Your next idea starts here.'),make('p','','Unlock a provider key, choose its model, then send a message. You can also compare two connected routes.'));host.append(empty);}else for(const msg of t.messages){const bubble=make('div','bubble '+(msg.role==='user'?'user':'assistant')+(msg.error?' error':''));bubble.append(make('div','bubble-meta',msg.role==='user'?'YOU':`${msg.provider||'MODEL'} · ${msg.model||'unverified'}`),make('div','bubble-text',msg.content));if(msg.role==='user'){const edit=make('button','text-button','Edit message');edit.type='button';edit.setAttribute('aria-label','Edit saved user message');edit.addEventListener('click',()=>{if(activeChatControllers.length)return toast('Stop the active model request before editing chat history.',true);const updated=prompt('Edit this locally saved user message (not resent to providers):',msg.content);if(updated===null)return;if(!updated.trim()||updated.length>10000)return toast('Message must contain 1–10,000 characters.',true);msg.content=updated;renderChat();saveSoon();toast('Saved user message edited locally; no request was sent.');});bubble.append(edit);}host.append(bubble);}host.scrollTop=host.scrollHeight;}
function newThread(){if(activeChatControllers.length)return toast('Stop the active model request before creating a thread.',true);if(state.threads.length>=120){if(!confirm('The 120-thread limit is reached. Creating another thread will delete the oldest one. Export your history first. Continue?'))return;state.threads.shift();}const t={id:uid('thread'),title:'New conversation',created:now(),messages:[]};state.threads.push(t);state.activeThreadId=t.id;renderChat();saveSoon();}
function clearThread(){if(activeChatControllers.length)return toast('Stop the active model request before clearing chat.',true);if(!confirm('Clear the currently selected conversation?'))return;thread().messages=[];thread().title='New conversation';renderChat();saveSoon();}
function exportThread(){const t=thread();download('mm-thread-'+t.id.replace(/[^a-z0-9_-]/gi,'')+'.json',JSON.stringify({format:'mm-studio-thread-v1',thread:t},null,2));}
function deleteThread(){if(activeChatControllers.length)return toast('Stop the active model request before deleting chat.',true);const current=thread();if(!confirm('Delete this conversation and all its locally saved messages? This cannot be undone. Export it first if needed.'))return;state.threads=state.threads.filter(t=>t.id!==current.id);if(!state.threads.length)state.threads=[{id:uid('thread'),title:'New conversation',created:now(),messages:[]}];state.activeThreadId=state.threads[state.threads.length-1].id;renderChat();saveSoon();toast('Conversation deleted locally.');}
function recordMessage(t,msg){t.messages.push({...msg,at:now()});t.messages=t.messages.slice(-150);renderChat();saveSoon();}
async function sendMessage(event){event?.preventDefault();const input=$('chat-input');const promptText=input.value.trim();if(!promptText)return;const id=$('chat-route').value;if(!id||!vault.get(id))return toast('Unlock your vault and select a connected key first.',true);if(activeChatControllers.length)return toast('A model request is already running.',true);const targets=[id];if($('compare-mode').checked){const second=$('compare-route').value;if(!second||second===id||!vault.get(second))return toast('Select a different, connected second route to compare.',true);targets.push(second);}const t=thread();if(t.messages.length>=147&&!confirm('This thread is near its 150-message limit. Older messages may be removed. Export this thread before continuing. Send anyway?'))return;if(!t.messages.length)t.title=promptText.slice(0,45);recordMessage(t,{role:'user',content:promptText});input.value='';$('chat-counter').textContent='0 / 10,000';$('send-chat').disabled=true;$('stop-chat').disabled=false;
const pending=targets.map(route=>{const controller=new AbortController();activeChatControllers.push(controller);audit('inference',route,'requested');return (async()=>{try{const cred=vault.get(route);const result=await callProvider(route,cred,[{role:'system',content:'Be helpful, accurate, and identify uncertainties.'},...historyForRoute(t.messages.slice(0,-1),route),{role:'user',content:promptText}],{signal:controller.signal});recordMessage(t,{role:'assistant',provider:route,model:result.model,content:result.text});audit('inference',route,'success',result.usage);return result;}catch(e){const cancelled=e.name==='AbortError';recordMessage(t,{role:'assistant',provider:route,model:vault.get(route)?.model,error:true,content:cancelled?'Request stopped.':errorText(e)});audit('inference',route,cancelled?'stopped':'failed');return null;}})()});await Promise.all(pending);activeChatControllers=[];$('send-chat').disabled=false;$('stop-chat').disabled=true;renderChat();}
function stopChat(){activeChatControllers.forEach(c=>c.abort());toast('Stop requested for all in-flight model requests.');}
function addCodeToChat(){const p=project();const content=p.files[p.active];$('chat-input').value=($('chat-input').value+'\n\nPlease review the following file '+p.active+':\n```\n'+content.slice(0,8000)+'\n```').trim().slice(0,10000);$('chat-counter').textContent=$('chat-input').value.length+' / 10,000';selectView('chat');$('chat-input').focus();}

function renderAudit(){const events=state.audit;const reqs=events.filter(x=>x.op==='inference');$('usage-total').textContent=reqs.length;$('usage-success').textContent=reqs.filter(x=>x.status==='success').length;const observed=reqs.filter(x=>Number.isSafeInteger(x.usage?.total_tokens));$('usage-tokens').textContent=observed.length?`${observed.reduce((s,x)=>s+x.usage.total_tokens,0)} observed / ${reqs.length} attempts`:'UNKNOWN';const body=clearNode($('audit-rows'));for(const a of events.slice(0,100)){const tr=make('tr');for(const value of [formatTime(a.at),`${a.provider||'local'} / ${a.op}`,a.status,a.usage?`${a.usage.total_tokens===null?'unknown':a.usage.total_tokens} tokens · ${a.usage.source}`:'unknown'])tr.append(make('td',value==='failed'?'bad':'',value));body.append(tr);}if(!events.length){const tr=make('tr'),td=make('td','','No activity recorded.');td.colSpan=4;tr.append(td);body.append(tr);}}
function flowStages(){const entered=$('workflow-stages').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);return entered.length?entered:FLOW_TEMPLATES[$('workflow-template').value]||FLOW_TEMPLATES.research;}
function renderFlowGraph(states=[]){const steps=flowStages(),host=clearNode($('workflow-graph'));if(steps.length>6){host.textContent=`${steps.length} stages entered. Maximum is 6; remove extras before starting.`;return;}steps.forEach((step,i)=>{const cell=make('div','flow-step '+(states[i]||'pending'),`${i+1}. ${step}`);cell.append(make('span','',({pending:'Waiting',running:'Running',done:'Complete',error:'Failed'})[states[i]]||''));host.append(cell);if(i!==steps.length-1)host.append(make('span','flow-arrow','→'));});}
function renderWorkflows(){routeChoices();renderFlowGraph();const host=clearNode($('workflow-history'));for(const w of state.workflows.slice(0,30)){const b=make('button','history-entry');b.append(make('strong','',`${w.template} · ${w.status}`),make('small','',`${formatTime(w.at)} · ${w.goal.slice(0,65)}`));b.addEventListener('click',()=>{$('workflow-results').textContent=w.steps.map(s=>`${s.stage}\n${s.content}`).join('\n\n---\n\n')});host.append(b);}if(!state.workflows.length)host.textContent='No runs recorded.';}
async function executeWorkflow(event){event.preventDefault();if(workflowController)return toast('Stop the current workflow first.',true);const id=$('workflow-route').value,cred=vault.get(id),goal=$('workflow-goal').value.trim(),template=$('workflow-template').value;if(!cred)return toast('Unlock a saved model key first.',true);if(!goal)return;const stages=flowStages();if(stages.length<2||stages.length>6)return toast('Choose between 2 and 6 workflow stages.',true);const controller=new AbortController();workflowController=controller;$('workflow-stop').disabled=false;$('workflow-start').disabled=true;$('workflow-results').textContent='Starting supervised workflow…';const result={id:uid('workflow'),at:now(),provider:id,template,goal,status:'running',steps:[]};let previous='';const status=stages.map(()=> 'pending');for(let i=0;i<stages.length;i++){if(controller.signal.aborted)break;status[i]='running';renderFlowGraph(status);const instruction=i===0?`Task: ${goal}\nStage 1 (${stages[i]}): ${stages[i]==='Plan implementation'?'Create a concrete implementation plan.': 'Produce a structured response.'}`:i===1?`Original task: ${goal}\nPrior stage output: ${previous.slice(0,7500)}\nStage 2 (${stages[i]}): improve or extend this work.`:`Original task: ${goal}\nPrior stage output: ${previous.slice(0,7500)}\nStage ${i+1} (${stages[i]}): carry out this named stage, using the prior output as input; clearly describe the result.`;audit('inference',id,'requested');try{const answer=await callProvider(id,cred,[{role:'user',content:instruction}],{signal:controller.signal});previous=answer.text;result.steps.push({stage:stages[i],content:answer.text,model:answer.model});status[i]='done';audit('inference',id,'success',answer.usage);$('workflow-results').textContent=result.steps.map(s=>`${s.stage} (${s.model})\n${s.content}`).join('\n\n---\n\n');}catch(e){status[i]='error';result.steps.push({stage:stages[i],content:e.name==='AbortError'?'Stopped by user':errorText(e)});result.status=e.name==='AbortError'?'stopped':'failed';audit('inference',id,result.status);break;}}if(result.status==='running')result.status=controller.signal.aborted?'stopped':result.steps.length===stages.length?'complete':'failed';renderFlowGraph(status);state.workflows.unshift(result);state.workflows=state.workflows.slice(0,40);$('workflow-results').textContent=result.steps.map(s=>`${s.stage}${s.model?' ('+s.model+')':''}\n${s.content}`).join('\n\n---\n\n');workflowController=null;$('workflow-stop').disabled=true;$('workflow-start').disabled=false;saveSoon();renderWorkflows();}

function knowledgeItems(query){const results=[];for(const note of state.notes){if((note.title+' '+note.content).toLowerCase().includes(query)){results.push({type:'note',id:note.id,title:note.title,content:note.content});}}for(const p of state.projects){for(const [name,source]of Object.entries(p.files)){if((p.name+' '+name+' '+source).toLowerCase().includes(query))results.push({type:'file',id:name,projectId:p.id,title:p.name+' / '+name,content:source});}}return results.slice(0,70);}
function resolveActiveKnowledge(){
 if(!activeNote)return null;
 if(activeNote.type==='note'){const note=state.notes.find(n=>n.id===activeNote.id);return note?{type:'note',id:note.id,title:note.title,content:note.content}:null;}
 if(activeNote.type==='file'){const p=state.projects.find(item=>item.id===activeNote.projectId);if(!p||!Object.hasOwn(p.files,activeNote.id))return null;return {type:'file',id:activeNote.id,projectId:p.id,title:p.name+' / '+activeNote.id,content:p.files[activeNote.id]};}
 return null;
}
function renderKnowledge(){const live=resolveActiveKnowledge();if(activeNote){activeNote=live;$('knowledge-preview').textContent=live?live.content.slice(0,15000):'Choose a search result.';}const query=$('knowledge-search').value.trim().toLowerCase(),results=knowledgeItems(query);$('note-count').textContent=state.notes.length+' notes';const host=clearNode($('knowledge-results'));results.forEach(result=>{const button=make('button','knowledge-result'+(activeNote?.id===result.id&&activeNote?.type===result.type?' active':''));button.append(make('b','',result.title),make('small','',result.content.slice(0,180)));button.addEventListener('click',()=>{activeNote=result;$('knowledge-preview').textContent=result.content.slice(0,15000);renderKnowledge();});host.append(button)});if(!results.length)host.append(make('p','hint-line','No local matches.'));}
function submitKnowledge(e){e.preventDefault();const title=$('knowledge-title').value.trim(),content=$('knowledge-content').value;if(!title||!content)return;if(state.notes.length>=MAX_NOTES)return toast('Note limit reached; export notes first.',true);state.notes.unshift({id:uid('note'),title,content,created:now()});$('knowledge-title').value='';$('knowledge-content').value='';renderKnowledge();saveSoon();toast('Knowledge note saved.');}
async function importKnowledge(input){const files=Array.from(input.files||[]);input.value='';if(files.length>15)return toast('Import at most 15 documents per batch.',true);const pending=[];try{for(const file of files){if(file.size>30_000_000)throw Error(`${file.name}: file exceeds 30 MB maximum`);if(file.name.toLowerCase().endsWith('.json')){const content=await file.text();const archived=parseNoteArchive(content);if(archived!==null){for(const note of archived)pending.push({...note,id:uid('note')});continue;}if(file.size>100000)throw Error(`${file.name}: text document exceeds 100 KB`);pending.push({id:uid('note'),title:file.name.slice(0,100),content:content.slice(0,100000),created:now()});continue;}if(file.size>100000)throw Error(`${file.name}: document exceeds 100 KB`);const content=await file.text();const prefix=file.name.toLowerCase().endsWith('.csv')?csvSummary(content)+'\n\n':'';pending.push({id:uid('note'),title:file.name.slice(0,100),content:(prefix+content).slice(0,100000),created:now()});}if(state.notes.length+pending.length>MAX_NOTES)throw Error(`Note capacity exceeded (maximum ${MAX_NOTES})`);if(!pending.length)return toast('No documents selected.',true);state.notes.push(...pending);saveSoon();renderKnowledge();toast(`${pending.length} note(s) imported.`);}catch(e){toast('Import failed: '+errorText(e),true);}}
function renderCapabilities(){const host=clearNode($('capability-list'));for(const [code,title,status,description]of CAPABILITIES){const row=make('article','capability-row');row.append(make('span','',status==='local'?'✓':status==='conditional'?'◇':'○'));const details=make('div');details.append(make('b','',`${code} · ${title}`),make('small','',description));row.append(details,make('span','tag '+(status==='local'?'good':status==='conditional'?'pending':'muted'),({local:'LOCAL',conditional:'EXTERNAL',partial:'PARTIAL',planned:'PLANNED'})[status]));host.append(row);}}
function renderSettings(){$('recovery-tools').hidden=recoveryRaw===null;if(recoveryRaw!==null)$('recovery-description').textContent='Unparseable '+(recoveryKind==='legacy'?'legacy B0.1/B0.2 project':'B0.3 browser state')+' detected. Original data has not been overwritten. Download a raw backup before resetting.';$('accent-select').value=state.preferences.accent;$('compact-toggle').checked=!!state.preferences.compact;$('platform-details').replaceChildren();for(const [k,v]of [['Build',VERSION],['Storage',storageMode()],['Security','Encrypted secrets; no keys in backups'],['Network','Provider requests only on explicit actions'],['GitHub','Public static source'],['Python','Optional Pyodide CDN runtime']]){const row=make('div');row.append(make('span','',k),make('strong','',v));$('platform-details').append(row);}}
function exportAll(){download('multimodel-studio-backup.json',JSON.stringify(state,null,2));}
async function importAll(file){if(!file||file.size>12_000_000)return toast('Backup file exceeds limit.',true);try{const value=JSON.parse(await file.text());if(!validateState(value))throw Error('Invalid or unsupported backup');if(!confirm('Replace ALL local projects, chat, notes, and audit with this backup? Encrypted key vault remains untouched.'))return;await replaceWorkspace(value);toast('Workspace restored and saved.');}catch(e){toast('Restore failed: '+errorText(e),true);}}
function renderAll(){labs?.refreshSavedDatasets();renderFiles();routeChoices();renderProviders();renderVault();renderChat();renderAudit();renderWorkflows();renderKnowledge();renderStats();renderSettings();renderCapabilities();}
function commandDialog(){const dialog=$('command-dialog'),input=$('command-search');input.value='';const render=()=>{const host=clearNode($('command-results'));for(const [id,label]of Object.entries(VIEWS)){if(!label.toLowerCase().includes(input.value.toLowerCase()))continue;const b=make('button','',label);b.addEventListener('click',()=>{dialog.close();selectView(id);});host.append(b);}};render();dialog.showModal();input.focus();input.oninput=render;}
function wire(){qsa('[data-view],[data-goto]').forEach(b=>b.addEventListener('click',()=>selectView(b.dataset.view||b.dataset.goto)));$('mobile-menu').addEventListener('click',()=>{const open=$('sidebar').classList.toggle('open');$('nav-backdrop').hidden=!open;$('mobile-menu').setAttribute('aria-expanded',String(open))});for(const b of [$('nav-backdrop'),$('sidebar-close')])b.addEventListener('click',()=>{$('sidebar').classList.remove('open');$('nav-backdrop').hidden=true;$('mobile-menu').setAttribute('aria-expanded','false');});$('global-command').addEventListener('click',commandDialog);$('command-close').addEventListener('click',()=>$('command-dialog').close());document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();commandDialog()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveNow().then(()=>toast(savedStatus())).catch(()=>{}) }if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&activeView==='workspace'){e.preventDefault();runCode()}});
$('project-select').addEventListener('change',e=>{state.activeProjectId=e.target.value;run.stop();renderFiles();saveSoon()});$('new-project').addEventListener('click',createProject);$('rename-project').addEventListener('click',renameProject);$('delete-project').addEventListener('click',deleteProject);$('snapshot-project').addEventListener('click',snapshot);$('snapshot-select').addEventListener('change',renderSnapshotActions);$('snapshot-action-run').addEventListener('click',manageSnapshot);$('restore-snapshot').addEventListener('click',restoreSnapshot);$('add-file').addEventListener('click',newFile);$('rename-file').addEventListener('click',renameFile);$('move-folder').addEventListener('click',moveFolder);$('delete-file').addEventListener('click',deleteFile);$('add-local-files').addEventListener('change',e=>importTextFiles(e.target));$('code-editor').addEventListener('input',editFile);$('code-editor').addEventListener('scroll',e=>{$('line-gutter').scrollTop=e.target.scrollTop});$('code-editor').addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const t=e.target,start=t.selectionStart,end=t.selectionEnd;t.setRangeText('  ',start,end,'end');editFile();}});$('run-code').addEventListener('click',runCode);$('stop-code').addEventListener('click',stopCode);$('preview-page').addEventListener('click',previewPage);$('clear-console').addEventListener('click',()=>{terminalLines=0;$('console-output').textContent='';});$('show-console').addEventListener('click',()=>showExecTab('console'));$('show-preview').addEventListener('click',()=>showExecTab('preview'));$('export-json').addEventListener('click',()=>download(project().name.replace(/\W+/g,'_')+'.json',projectJSON()));$('export-zip').addEventListener('click',()=>download(project().name.replace(/\W+/g,'_')+'.zip',zipFiles(project().files),'application/zip'));$('import-project').addEventListener('change',e=>{const file=e.target.files?.[0];e.target.value='';importProject(file)});
$('provider-search').addEventListener('input',e=>renderProviders(e.target.value));$('vault-form').addEventListener('submit',submitVault);$('vault-lock').addEventListener('click',()=>{vault.lock();renderAll();toast('Key vault locked.');});$('vault-wipe').addEventListener('click',async()=>{if(!confirm('Permanently erase ALL encrypted API keys from this device?'))return;if(!confirm('Confirm permanent vault deletion. This cannot be undone.'))return;await vault.erase();renderAll();toast('Encrypted vault erased.');});$('key-provider').addEventListener('change',e=>{$('key-model').value=vault.get(e.target.value)?.model||providerById(e.target.value)?.model||'';$('key-account').value=vault.get(e.target.value)?.account||'';});$('save-key').addEventListener('click',()=>{if(!vault.isUnlocked){toast('First create or unlock your vault with a passphrase. Your provider fields will remain filled.',true);$('vault-password').focus();$('vault-password').scrollIntoView({behavior:'smooth',block:'center'});}});$('key-form').addEventListener('submit',submitKey);
$('chat-route').addEventListener('change',renderCompareRoute);$('compare-mode').addEventListener('change',renderCompareRoute);$('chat-form').addEventListener('submit',sendMessage);$('chat-input').addEventListener('input',e=>$('chat-counter').textContent=e.target.value.length+' / 10,000');$('stop-chat').addEventListener('click',stopChat);$('send-selected-code').addEventListener('click',addCodeToChat);$('new-chat').addEventListener('click',newThread);$('clear-chat').addEventListener('click',clearThread);$('thread-search').addEventListener('input',renderThreadList);$('export-chat-thread').addEventListener('click',exportThread);$('delete-chat-thread').addEventListener('click',deleteThread);$('export-audit').addEventListener('click',()=>download('mm-audit.json',JSON.stringify(state.audit,null,2)));$('clear-audit').addEventListener('click',()=>{if(!confirm('Clear local audit log?'))return;state.audit=[];saveSoon();renderAudit();});
$('workflow-template').addEventListener('change',()=>{$('workflow-stages').value=FLOW_TEMPLATES[$('workflow-template').value].join('\n');renderFlowGraph();});$('workflow-stages').addEventListener('input',()=>renderFlowGraph());$('workflow-form').addEventListener('submit',executeWorkflow);$('workflow-stop').addEventListener('click',()=>{workflowController?.abort();toast('Workflow cancellation requested.');});$('knowledge-form').addEventListener('submit',submitKnowledge);$('knowledge-search').addEventListener('input',renderKnowledge);$('knowledge-import').addEventListener('change',e=>importKnowledge(e.target));$('knowledge-export').addEventListener('click',()=>download('mm-knowledge.json',exportNoteArchive(state.notes)));$('knowledge-delete').addEventListener('click',()=>{if(!activeNote||activeNote.type!=='note')return toast('Select a saved note to delete.',true);if(!confirm(`Delete note ${activeNote.title}?`))return;state.notes=state.notes.filter(n=>n.id!==activeNote.id);activeNote=null;$('knowledge-preview').textContent='Choose a search result.';renderKnowledge();saveSoon();});$('knowledge-to-chat').addEventListener('click',()=>{activeNote=resolveActiveKnowledge();if(!activeNote)return toast('Select a current note or project file first.',true);$('chat-input').value=`Use the following local reference (${activeNote.title}):\n${activeNote.content.slice(0,9000)}`;$('chat-counter').textContent=$('chat-input').value.length+' / 10,000';selectView('chat');});
$('accent-select').addEventListener('change',e=>{state.preferences.accent=e.target.value;document.body.dataset.accent=e.target.value;saveSoon()});$('compact-toggle').addEventListener('change',e=>{state.preferences.compact=e.target.checked;document.body.classList.toggle('compact',e.target.checked);saveSoon()});$('backup-all').addEventListener('click',exportAll);$('restore-all').addEventListener('change',e=>{const file=e.target.files?.[0];e.target.value='';importAll(file)});$('reset-all').addEventListener('click',async()=>{if(!confirm('Reset projects, notes, chat and audit? API keys remain encrypted in the separate vault.'))return;if(!confirm('This removes the saved workspace from this browser. Confirm?'))return;try{await replaceWorkspace(freshState());toast('Application data reset and saved.');}catch(e){toast('Reset was not applied: '+errorText(e),true);}});$('recovery-backup').addEventListener('click',()=>{if(recoveryRaw!==null)download('mm-unreadable-'+(recoveryKind||'state')+'-backup.txt',recoveryRaw,'text/plain');});$('recovery-reset').addEventListener('click',async()=>{if(recoveryRaw===null)return;if(!confirm('Reset this unreadable saved record? Download its raw backup first.'))return;try{await replaceWorkspace(freshState());if(recoveryKind==='legacy')localStorage.removeItem('mm-platform-browser-b01');recoveryRaw=null;recoveryKind=null;renderSettings();toast('Unreadable saved data replaced and saved; new workspace initialized.');}catch(e){toast('Reset failed: '+errorText(e),true);}});$('cache-refresh').addEventListener('click',async()=>{
 const controller=navigator.serviceWorker?.controller;
 if(!controller)return toast('Open the site over HTTPS and reload to initialize service worker.',true);
 const button=$('cache-refresh');button.disabled=true;button.textContent='Refreshing…';
 try{
  if(typeof MessageChannel!=='function')throw Error('MessageChannel unavailable in this browser');
  await new Promise((resolve,reject)=>{
   const channel=new MessageChannel();
   const timer=setTimeout(()=>{channel.port1.close();reject(Error('No service worker confirmation within 20 seconds'));},20000);
   channel.port1.onmessage=event=>{clearTimeout(timer);channel.port1.close();if(event.data?.ok)resolve();else reject(Error(event.data?.error||'Offline refresh failed'));};
   try{controller.postMessage({type:'REFRESH'},[channel.port2]);}catch(error){clearTimeout(timer);channel.port1.close();reject(error);}
  });
  toast('Offline application cache refreshed successfully.');
 }catch(error){toast('Offline cache refresh failed: '+errorText(error),true);}
 finally{button.disabled=false;button.textContent='Refresh offline cache';}
});}
async function boot(){try{const stored=await read('state.v1');if(stored!==null){if(!validateState(stored)){recoveryRaw=JSON.stringify(stored);recoveryKind='state';storageFailed=true;state=freshState();toast('Unreadable B0.3 state detected. Original data preserved; use Settings → Recovery before saving.',true);}else state=stored;}else{let legacy=null;let raw=null;try{raw=localStorage.getItem('mm-platform-browser-b01');if(raw)legacy=JSON.parse(raw);}catch{recoveryRaw=raw;recoveryKind='legacy';}if(legacy){try{state=migrateLegacy(legacy);}catch{recoveryRaw=raw;recoveryKind='legacy';}}if(!state)state=freshState();await write('state.v1',state);if(recoveryRaw)toast('Legacy project unreadable: raw bytes preserved. Open Settings → Recovery.',true);}}catch(e){state=freshState();storageFailed=true;toast('Browser storage unavailable. Export your work frequently: '+errorText(e),true);}
$('key-provider').replaceChildren(...PROVIDERS.map(p=>new Option(p.name,p.id)));$('key-model').value=PROVIDERS[0].model;
run=new RuntimeRunner(document.body,(active,lang)=>{$('stop-code').disabled=!active;$('runner-status').textContent=active?'Running '+lang:'Idle';});run.onStop=msg=>{if(lastRunLang==='python'&&pythonRuntimeStatus.startsWith('RUNNING'))pythonRuntimeStatus=msg.includes('timed out')?'TIMED OUT THIS SESSION':'STOPPED THIS SESSION';printConsole(msg);};
$('workflow-stages').value=FLOW_TEMPLATES.research.join('\n');wire();labs=setupLabs({el,toast,download,getDatasets:()=>state.datasets||[],commitDatasets:async(next)=>{if(storageFailed)throw Error('Local storage is in recovery mode; export a backup first.');const previous=state.datasets;state.datasets=next;try{await saveNow();}catch(e){state.datasets=previous;throw e;}}});document.body.dataset.accent=state.preferences?.accent||'cyan';document.body.classList.toggle('compact',!!state.preferences?.compact);renderAll();$('save-indicator').textContent=storageFailed?'Save failed — export a backup':savedStatus();const initial=location.hash.slice(1);selectView(VIEWS[initial]?initial:'overview');if('serviceWorker' in navigator && location.protocol!=='file:'){try{await navigator.serviceWorker.register('./sw.js',{scope:'./'});}catch(e){console.warn('Offline shell unavailable:',e.message);}}}
boot().catch(e=>{console.error('Initialization error',e);toast('Initialization error: '+errorText(e),true)});
